column3:
                    js_code="// PIN Login for terminal shared sessions
const staffSession = await pux.offline.pinLogin('1234');

console.log(`Logged in as: ${staffSession.user.name}`);
console.log(`Role: ${staffSession.user.role}`);",

                    js_code="// Adjust stock for a specific SKU
const result = await pux.products.adjustStock('prod_uuid', {
    adjustment: 25,
    reason: 'Received shipment batch #902'
});

console.log(`New Level: ${result.new_quantity}`);",

                    js_code="// Fetch audit logs
const history = await pux.products.history('prod_uuid');

history.forEach(event => {
    console.log(`[${event.changed_at}] ${event.action}: ${event.changes_summary}`);
});",

                    js_code="// Create a production order
const order = await pux.orders.create({
    customer: 'cust_uuid',
    items: [
        { product: 'prod_1', quantity: 2, price: 15.00 },
        { product: 'prod_2', quantity: 1, price: 99.99 }
    ],
    payment_method: 'card',
    status: 'completed'
});

console.log(`Receipt generated: ${order.order_number}`);",

                    js_code="// Fetch intelligent restock suggestions
const recommendations = await pux.reports.restockRecommendations();

recommendations.forEach(rec => {
    console.log(`Product: ${rec.name}`);
    console.log(`Sales Velocity: ${rec.avg_daily_sales}/day`);
    console.log(`Recommended Restock: ${rec.recommended_restock} units`);
});",

